def policy(me, opponent):
    import numpy as np

    # Setup board
    board = np.zeros((19, 19), dtype=np.int8)
    for r, c in me:
        if 1 <= r <= 19 and 1 <= c <= 19:
            board[r-1, c-1] = 1
    for r, c in opponent:
        if 1 <= r <= 19 and 1 <= c <= 19:
            board[r-1, c-1] = 2

    dirs = [(-1,0),(1,0),(0,-1),(0,1)]

    # Analyze groups
    visited = np.zeros((19, 19), dtype=bool)
    group_libs = {}
    pos_to_rep = {}
    capture_moves = {}
    save_moves = {}

    for r in range(19):
        for c in range(19):
            if board[r, c] != 0 and not visited[r, c]:
                color = board[r, c]
                group = []
                libs = set()
                stack = [(r, c)]
                rep = (r, c)
                while stack:
                    cr, cc = stack.pop()
                    if visited[cr, cc]:
                        continue
                    visited[cr, cc] = True
                    group.append((cr, cc))
                    pos_to_rep[(cr, cc)] = rep
                    for dr, dc in dirs:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < 19 and 0 <= nc < 19:
                            if board[nr, nc] == 0:
                                libs.add((nr, nc))
                            elif board[nr, nc] == color and not visited[nr, nc]:
                                stack.append((nr, nc))

                lib_count = len(libs)
                for pos in group:
                    group_libs[pos] = lib_count

                if lib_count == 1:
                    lib_pos = list(libs)[0]
                    if color == 2:
                        capture_moves[lib_pos] = capture_moves.get(lib_pos, 0) + len(group)
                    else:
                        save_moves[lib_pos] = save_moves.get(lib_pos, 0) + len(group)

    # Priority 1: Capture
    if capture_moves:
        best = max(capture_moves.items(), key=lambda x: x[1])
        r, c = best[0]
        return (r+1, c+1)

    # Priority 2: Save (check validity)
    if save_moves:
        # Sort by size descending
        sorted_saves = sorted(save_moves.items(), key=lambda x: -x[1])
        for (r, c), size in sorted_saves:
            # Check if suicide (though it shouldn't be if it's a liberty)
            # But check if it becomes self-atari with no capture
            board[r, c] = 1
            valid = False
            # Check adjacent empty
            for dr, dc in dirs:
                nr, nc = r+dr, c+dc
                if 0 <= nr < 19 and 0 <= nc < 19 and board[nr, nc] == 0:
                    valid = True
                    break
            if not valid:
                # Check capture
                for dr, dc in dirs:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < 19 and 0 <= nc < 19 and board[nr, nc] == 2:
                        if group_libs.get((nr, nc), 1) == 1:
                            valid = True
                            break
            board[r, c] = 0
            if valid:
                return (r+1, c+1)

    # Priority 3: Heuristic
    best_score = -999999
    best_move = (0, 0)

    for r in range(19):
        for c in range(19):
            if board[r, c] != 0:
                continue

            # Validity check
            board[r, c] = 1
            valid = False

            # Adjacent empty?
            for dr, dc in dirs:
                nr, nc = r+dr, c+dc
                if 0 <= nr < 19 and 0 <= nc < 19 and board[nr, nc] == 0:
                    valid = True
                    break

            # Adjacent capture?
            if not valid:
                for dr, dc in dirs:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < 19 and 0 <= nc < 19 and board[nr, nc] == 2:
                        if group_libs.get((nr, nc), 1) == 1:
                            valid = True
                            break

            # Adjacent safe connection?
            if not valid:
                for dr, dc in dirs:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < 19 and 0 <= nc < 19 and board[nr, nc] == 1:
                        if group_libs.get((nr, nc), 0) > 1:
                            valid = True
                            break

            board[r, c] = 0

            if not valid:
                continue

            # Scoring
            score = 0

            # Nearby stones
            my_adj = 0
            opp_adj = 0
            for dr, dc in dirs:
                nr, nc = r+dr, c+dc
                if 0 <= nr < 19 and 0 <= nc < 19:
                    if board[nr, nc] == 1:
                        my_adj += 1
                    elif board[nr, nc] == 2:
                        opp_adj += 1

            score += my_adj * 10
            score += opp_adj * 6

            # Avoid self-atari (simple)
            if my_adj > 0:
                # Check if this puts us in atari
                # If all neighbors are either opponent or me or edge, and only 1 empty total
                empty_neighbors = 0
                for dr, dc in dirs:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < 19 and 0 <= nc < 19:
                        if board[nr, nc] == 0:
                            empty_neighbors += 1
                if empty_neighbors == 1:
                    score -= 30

            # Line preference
            dist_edge = min(r, 18-r, c, 18-c)
            if dist_edge == 0:
                score -= 15
            elif dist_edge == 1:
                score += 3
            elif dist_edge == 2:
                score += 6
            elif dist_edge == 3:
                score += 4

            # Star points
            if (r in [3, 9, 15] and c in [3, 9, 15]):
                score += 10

            # Center
            score += (9 - abs(r-9)) * 0.3

            if score > best_score:
                best_score = score
                best_move = (r, c)

    if best_move != (0, 0):
        return (best_move[0]+1, best_move[1]+1)
    return (0, 0)
